create extension if not exists "pgcrypto";
create type lifecycle_status as enum ('PROSPECT','ONBOARDING','KYC','TRIAL','ACTIVE','UPGRADE','DOWNGRADE','RENEWAL','SUSPENDED','CANCELLED','ARCHIVED');
create table if not exists organizations (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table if not exists customers (id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id), customer_code text unique not null, company_name text not null, legal_name text, email text not null, phone text, website text, address text, city text, state text, country text, gstin text, cin text, industry text, status lifecycle_status not null default 'PROSPECT', account_owner text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists tenants (id uuid primary key default gen_random_uuid(), customer_id uuid not null references customers(id) on delete cascade, name text not null, slug text unique not null, status lifecycle_status not null default 'ONBOARDING', created_at timestamptz not null default now());
create table if not exists users (id uuid primary key, customer_id uuid references customers(id) on delete cascade, email text not null, name text, status text not null default 'ACTIVE', last_login_at timestamptz, created_at timestamptz not null default now());
create table if not exists roles (id uuid primary key default gen_random_uuid(), name text unique not null, scope text not null default 'MASTER'); create table if not exists permissions (id uuid primary key default gen_random_uuid(), code text unique not null, description text); create table if not exists role_permissions (role_id uuid references roles(id) on delete cascade, permission_id uuid references permissions(id) on delete cascade, primary key(role_id,permission_id)); create table if not exists user_roles (user_id uuid references users(id) on delete cascade, role_id uuid references roles(id) on delete cascade, customer_id uuid references customers(id) on delete cascade, primary key(user_id,role_id,customer_id));
create table if not exists products (id uuid primary key default gen_random_uuid(), product_code text unique not null, name text not null, description text, version text, status text not null default 'ACTIVE', created_at timestamptz not null default now()); create table if not exists product_modules (id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id) on delete cascade, name text not null, code text not null, unique(product_id,code)); create table if not exists product_features (id uuid primary key default gen_random_uuid(), module_id uuid references product_modules(id) on delete cascade, product_id uuid not null references products(id) on delete cascade, name text not null, code text not null, unique(product_id,code));
create table if not exists plans (id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id), name text not null, status text not null default 'ACTIVE', user_limit integer, storage_gb integer, api_limit integer, unique(product_id,name)); create table if not exists plan_entitlements (id uuid primary key default gen_random_uuid(), plan_id uuid not null references plans(id) on delete cascade, feature_id uuid references product_features(id), entitlement_key text not null, entitlement_value jsonb not null default 'true');
create table if not exists subscriptions (id uuid primary key default gen_random_uuid(), customer_id uuid not null references customers(id), product_id uuid not null references products(id), plan_id uuid not null references plans(id), status text not null, starts_at timestamptz, expires_at timestamptz, renewal_mode text, created_at timestamptz not null default now()); create table if not exists customer_products (id uuid primary key default gen_random_uuid(), customer_id uuid not null references customers(id), product_id uuid not null references products(id), tenant_id uuid references tenants(id), status text not null default 'ACTIVE', unique(customer_id,product_id,tenant_id));
create table if not exists customer_configurations (id uuid primary key default gen_random_uuid(), customer_id uuid references customers(id) on delete cascade, product_id uuid references products(id), config_key text not null, config_value jsonb not null, scope text not null, environment text not null, is_sensitive boolean not null default false, updated_by uuid references users(id), updated_at timestamptz not null default now()); create table if not exists industry_profiles (id uuid primary key default gen_random_uuid(), name text unique not null, configuration jsonb not null default '{}');
create table if not exists infrastructure (id uuid primary key default gen_random_uuid(), customer_id uuid references customers(id), provider text not null, server text not null, environment text not null, region text, hostname text, status text, cpu text, ram text, storage text, database_name text, ssl_status text, last_health_check timestamptz, created_at timestamptz not null default now()); create table if not exists infrastructure_services (id uuid primary key default gen_random_uuid(), infrastructure_id uuid not null references infrastructure(id) on delete cascade, name text not null, status text not null); create table if not exists deployments (id uuid primary key default gen_random_uuid(), customer_id uuid references customers(id), product_id uuid references products(id), environment text not null, version text, status text not null, started_at timestamptz, completed_at timestamptz, triggered_by uuid references users(id), provider_payload jsonb); create table if not exists integrations (id uuid primary key default gen_random_uuid(), customer_id uuid references customers(id), name text not null, type text, status text, configuration jsonb not null default '{}');
create table if not exists kyc_documents (id uuid primary key default gen_random_uuid(), customer_id uuid not null references customers(id) on delete cascade, document_type text not null, storage_path text not null, verification_status text not null default 'PENDING', verification_date timestamptz, remarks text, uploaded_at timestamptz not null default now()); create table if not exists audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references users(id), action text not null, resource_type text not null, resource_id text not null, before_value jsonb, after_value jsonb, created_at timestamptz not null default now());
create index if not exists idx_customers_status on customers(status); create index if not exists idx_tenants_customer on tenants(customer_id); create index if not exists idx_audit_resource on audit_logs(resource_type,resource_id);
alter table customers enable row level security; alter table tenants enable row level security; alter table customer_configurations enable row level security; alter table kyc_documents enable row level security;
create policy customer_isolation on customers for all using (id::text = coalesce(auth.jwt()->>'customer_id',id::text)); create policy tenant_isolation on tenants for all using (customer_id::text = coalesce(auth.jwt()->>'customer_id',customer_id::text)); create policy config_isolation on customer_configurations for all using (customer_id::text = coalesce(auth.jwt()->>'customer_id',customer_id::text)); create policy kyc_isolation on kyc_documents for all using (customer_id::text = coalesce(auth.jwt()->>'customer_id',customer_id::text));
